import hashlib,json,os,shutil,statistics,subprocess,tempfile,time,ctypes
from pathlib import Path
os.sched_setaffinity(0,{0})
binaries={k:str(Path(v).resolve()) for k,v in {'parent':'build/review-j08-final2/release/mus-solver','candidate':'build/review-j09-final/release/mus-solver'}.items()}
output=Path('/tmp/mus-review-j09-small-performance.json')
data={'parent_commit':'46af298','method':'CPU0, seed7, 100 new tables per timed batch, 45 cells per table, one training iteration and one evaluation sample per cell. Actual Btrfs workspace. Three alternating paired batches, then five additional pairs if gate is exceeded. Each batch amplifies the cost of many tiny cells; times include CLI startup and publication. Final policy files compared for every table. Prior own dirty data synchronized outside each timed batch.','runs':[],'summary':[],'binary_sha256':{v:hashlib.sha256(Path(p).read_bytes()).hexdigest() for v,p in binaries.items()}}
def save():output.write_text(json.dumps(data,indent=2)+'\n')
def hashes(directory):return {p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(directory.iterdir()) if p.name not in ('training.lock','recovery.txt')}
with tempfile.TemporaryDirectory(prefix='recovery-small-',dir=str(Path('build/review-j17-sync-io').resolve())) as tmp:
 root=Path(tmp);reference=None
 def batch(version,repeat):
  global reference
  directories=[root/f'{version}-{repeat}-{i}' for i in range(100)]
  fd=os.open(root,os.O_RDONLY|os.O_DIRECTORY)
  try:
   if ctypes.CDLL(None,use_errno=True).syncfs(fd)!=0:raise RuntimeError('syncfs failed')
  finally:os.close(fd)
  command=[binaries[version],'--format','ordago-score','--score','35:35','--iterations','1','--evaluation-samples','1','--seed','7','--continuation']
  rss=0
  with tempfile.TemporaryFile(mode='w+') as log:
   start=time.perf_counter()
   for directory in directories:
    args=[*command,str(directory)]
    pid=os.posix_spawn(args[0],args,os.environ,file_actions=[(os.POSIX_SPAWN_DUP2,log.fileno(),1),(os.POSIX_SPAWN_DUP2,log.fileno(),2)])
    _,status,usage=os.wait4(pid,0);rss=max(rss,usage.ru_maxrss)
    if status:log.seek(0);raise RuntimeError((status,log.read()))
   elapsed=time.perf_counter()-start
  for directory in directories:
   h=hashes(directory);assert len(h)==46
   if reference is None:reference=h
   assert h==reference
   shutil.rmtree(directory)
  row={'version':version,'repeat':repeat,'wall_seconds':elapsed,'peak_rss_kib':rss,'tables':100,'cells':4500,'all_policy_files_identical':True,'command_prefix':command}
  data['runs'].append(row);save();print(version,repeat,elapsed,rss,flush=True)
 def summary(confirmation):
  rows=[r for r in data['runs'] if (r['repeat']>3)==confirmation];s={'confirmation':confirmation}
  for m in ['wall_seconds','peak_rss_kib']:
   a=statistics.median(r[m] for r in rows if r['version']=='parent');b=statistics.median(r[m] for r in rows if r['version']=='candidate');s[m]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
  s['gate_triggered']=s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25
  data['summary'].append(s);save();print('SUMMARY',json.dumps(s),flush=True);return s['gate_triggered']
 for repeat in range(1,4):
  for version in (['parent','candidate'] if repeat%2 else ['candidate','parent']):batch(version,repeat)
 if summary(False):
  for repeat in range(4,9):
   for version in (['parent','candidate'] if repeat%2 else ['candidate','parent']):batch(version,repeat)
  data['blocked']=summary(True)
 else:data['blocked']=False
 data['reference_policy_sha256']=reference;save();print('DONE',flush=True)
